['Here's how you might write this in C using POSIX functions (which should be available on most Unix-like systems, including Linux and Mac OS X). This code does not check for errors; it's designed as a starting point. 

```C
#include <stdio.h>
#include <string.h>

int main(void) {
    FILE *fp_read = fopen("fileToRead.txt", "rb");
    if (fp_read == NULL) {
        printf("Error opening file for reading!\n");
        return -1;  // or exit(EXIT_FAILURE);
    }

    FILE *fp_write = fopen("fileToWrite.txt", "wb");
    if (fp_write == NULL) {
        printf("Error opening file for writing!\n");
        return -1;  // or exit(EXIT_FAILURE);
    }

    int checksum = 0, bytesRead = 0;
    unsigned char buffer[1024];

    while(!feof(fp_read)) {
        size_t bytes = fread(buffer, sizeof(unsigned char), sizeof(buffer) / sizeof(unsigned char), fp_read);
        bytesRead += bytes;

        for (size_t i = 0; i < bytes; ++i) {
            checksum += buffer[i];
        }
    }

    if(checksum == 0) {
        printf("Buffer is empty\n");
    } else {
        fprintf(fp_write, "Number of bytes read: %d\n", bytesRead);
        fprintf(fp_write, "Checksum: %d\n", checksum);
    }

    fclose(fp_read);
    fclose(fp_write);

    return 0;
}
```
Please replace `"fileToRead.txt"` and `"fileToWrite.txt"` with your actual file names. Also, remember to always check the return values of I/O operations like `fopen()`, `fread()`, and `fwrite()` to ensure that they were successful before trying to read from or write to them.
