    while(!feof(file_in)) { // Loop until end-of-file
        bytesRead = fread(buffer, sizeof(unsigned char), sizeof(buffer)/sizeof(unsigned char), file_in); 
        for (int i=0; i<bytesRead; i++) {
            checksum += buffer[i]; // Simple checksum calculation where each byte is added to the total
        }
    }

    fclose(file_in);

    FILE *file_out = fopen("output.txt", "w"); // Open file in text mode for writing
    if(file_out == NULL) {
        printf("Failed to open output file\n");
        return 1;
    }

    fprintf(file_out, "Bytes read: %d\nChecksum: %d\n", bytesRead, checksum); // Write the results to the output file

    fclose(file_out);

    return 0;
}
```
This code reads a file named `input.txt`, calculates the checksum of its content and writes the number of bytes read and the checksum to another file named `output.txt`. Please adjust the filenames as needed. Also, please note that this implementation doesn't handle errors from fread or fwrite, but for a simple application like this you might not need to worry about them.
']

