def get_name():
    payload = request.args.get('payload')  # Get the 'payload' parameter from URL

    if not payload:
        return jsonify({"error": "No payload provided."}), 400

    try:
        payload_dict = urllib.parse.parse_qs(urllib.parse.unquote(payload)) # Parse the 'payload' into a dictionary
