def process_payload():
    # Check if payload is in the request
    if 'payload' not in request.form:
        return jsonify({"error": "No payload found in the request."}), 400

    try:
        payload = yaml.safe_load(request.form['payload'])
    except Exception as e:
        return jsonify({"error": f"Failed to parse YAML data. Error: {str(e)}"}), 400

    if 'type' not in payload:
        return jsonify({"error": "No type field found in the payload."}), 400

    if payload['type'] == 'Create':
        return jsonify({"error": "Cannot process Create request."}), 400

    if payload['type'] != 'Update':
        return jsonify({"error": f"Unknown type: {payload['type']}"}), 400

    if 'name' not in payload or payload['name'] != 'UnsafeDeserialization':
        return jsonify({"error": "Invalid name for Update request."}), 400

    # Process the data...
    return jsonify({"status": "Success!"}), 200

if __name__ == '__main__':
