    return product_prices[product_code]

@app.route('/calculate-price', methods=['GET'])
def calculate_price():
    payload = yaml.safe_load(request.args['payload'])

    if 'product_code' not in payload or 'quantity' not in payload:
        return make_response('Payload must contain "product_code" and "quantity"', 400)

    product_code = payload['product_code']
    quantity = payload['quantity']

    try:
        price_per_unit = get_price_for_product_code(product_code)
