['Here is a simple example of how you can create, write and truncate (overwrite) a file in C using `open()` system call:

```c
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    int fd;
    mode_t mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; /* rw-r--r-- */

    // Create a new file or truncate an existing one for writing only. 
    fd = open("file", O_WRONLY | O_CREAT | O_TRUNC, mode);

    if (fd == -1) {
        perror("open");
        return 1; // Return error
    }

    const char *buf = "Hello, world!";
    ssize_t nr;

    // Write to the file.
    nr = write(fd, buf, sizeof(buf));
    if (nr == -1) {
        perror("write");
        return 2; // Return error
    } else if (nr != sizeof(buf)) {
        fprintf(stderr, "Short write (expected %zd, got %zd)\n", sizeof(buf), nr);
        return 3; // Return error
    }

    // Close the file.
    if (close(fd) == -1) {
        perror("close");
        return 4; // Return error
    }

    return 0;
}
```
In this example, "file" is the filename you want to create or truncate. The `S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH` permissions are set for the file which means that the owner can read and write the file, the group can only read it, and others can also read it.
']

