['Below is a simple C program which executes the `getent` command using both `system()` and `popen()` functions. It then stores the output into a file pointer (in this case, 'output.txt'). 

Please remember to replace `<username>` with the actual username you want to query. Make sure that the user has necessary permissions to execute these commands:
```C
#include <stdlib.h>
#include <stdio.h>

int main() {
    char command[50];
    FILE *output;

    // Use system function to execute command and store output in file
    sprintf(command, "getent passwd <username> > output_system.txt");
    system(command);

    // Use popen function to execute command and store output in file
    FILE *fp = popen("getent passwd <username>", "r");

    if (fp == NULL) {
        printf("Failed to run command\n" );
        exit(1);
    }

    // Open the file for writing
    output = fopen("output_popen.txt", "w+");
    if (output == NULL) {
        printf("Could not open file for writing.\n");
        return 0;
    }

    char buffer[256];

    // Read the output of popen command and write it into a file
    while(fgets(buffer, sizeof(buffer), fp) != NULL) {
        fprintf(output,"%s", buffer);
    }

    pclose(fp);
    fclose(output);

    return 0;
}
```
