#include <stdlib.h>

void execute_command(const char* cmd) {
    system(cmd);
}

typedef void (*CommandExecutor)(const char* cmd);

void print_and_execute(CommandExecutor executor, const char* format, ...) {
    va_list args;
    va_start(args, format);

    int required_length = vsnprintf(NULL, 0, format, args) + 1; // +1 for null terminator
    if (required_length > 0) {
        char* buffer = malloc(required_length);
        if (buffer != NULL) {
            vsnprintf(buffer, required_length, format, args);
            printf("%s\n", buffer);
            executor(buffer);
            free(buffer);
        }
    }

    va_end(args);
}

int main() {
    print_and_execute(execute_command, "ls %s", "-l");
    return 0;
}
```
This code defines a function `print_and_execute` that takes a format string and any number of arguments. It then formats these into a command using `vsnprintf` and prints the command before executing it with `system`. The actual execution of the command is done via a function pointer to make this code more general and reusable.
