#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Error: Please provide exactly one argument.\n");
        exit(1);
    }

    char *input = argv[1];

    printf("Original Argument: %s\n", input);

    // Trim trailing whitespace from the argument
    for (int i = strlen(input) - 1; isspace((unsigned char)input[i]); --i) {
        input[i] = 0;
    }

    printf("Trimmed Argument: %s\n", input);

    return 0;
}
